import numpy as np

def heuristic(dist_m, turn_deg, swath_len_m, energy_left_frac, depot_dist_m, fits):
    """Return a positive desirability score for each candidate swath."""
    # Primary signal: strictly inversely proportional to transit distance (favors adjacent swaths).
    base_score = 1.0 / (dist_m + 1e-6)

    # Hard penalty for candidates that do not fit in the current battery sortie.
    feasibility_mask = np.where(fits == 0.0, 0.5, 1.0)

    # Soft bonus: when battery is low (<20%), prefer swaths ending closer to depot (inverse distance).
    energy_threshold = 0.20
    if energy_left_frac < energy_threshold:
        return base_score * feasibility_mask * (depot_dist_m + 1e-6) / (depot_dist_m + 1e-6 + dist_m)
    else:
        return base_score * feasibility_mask
